import type { FieldModification } from '../FieldModification'
import type { FieldModificationsBuilder } from '../WixDataFieldModificationsBuilder'
import { AggregatingValidator, messages } from '../../errors'
import { isNumber } from '../../utils'

export abstract class BaseFieldModificationsBuilder<Self>
  implements FieldModificationsBuilder<Self>
{
  protected readonly fieldModifications: FieldModification[]
  protected readonly ownInvalidArguments: string[]

  constructor(origin: {
    invalidArguments?: string[]
    fieldModifications?: FieldModification[]
  }) {
    this.ownInvalidArguments = origin.invalidArguments ?? []
    this.fieldModifications = origin.fieldModifications ?? []
  }

  protected abstract copy(params: {
    invalidArguments?: string[]
    addFieldModification: FieldModification
  }): Self

  incrementField(fieldName: string, by: number): Self {
    const [invalidArguments] = this.patchValidator('.incrementField')
      .arityIsTwo(arguments)
      .isNumber(fieldName, by)
      .validateAndAggregate()

    return this.copy({
      invalidArguments,
      addFieldModification: {
        fieldPath: fieldName,
        action: 'INCREMENT_FIELD',
        value: by,
      },
    })
  }

  setField(fieldName: string, value: any): Self {
    const [invalidArguments] = this.patchValidator('.setField')
      .arityIsTwo(arguments)
      .validateAndAggregate()

    return this.copy({
      invalidArguments,
      addFieldModification: {
        fieldPath: fieldName,
        action: 'SET_FIELD',
        value,
      },
    })
  }

  appendToArray(fieldName: string, value: any): Self {
    const [invalidArguments] = this.patchValidator('.appendToArray')
      .arityIsTwo(arguments)
      .validateAndAggregate()

    return this.copy({
      invalidArguments,
      addFieldModification: {
        fieldPath: fieldName,
        action: 'APPEND_TO_ARRAY',
        value,
      },
    })
  }

  removeFromArray(fieldName: string, value: any): Self {
    const [invalidArguments] = this.patchValidator('.removeFromArray')
      .arityIsTwo(arguments)
      .validateAndAggregate()

    return this.copy({
      invalidArguments,
      addFieldModification: {
        fieldPath: fieldName,
        action: 'REMOVE_FROM_ARRAY',
        value,
      },
    })
  }

  removeField(fieldName: string): Self {
    const [invalidArguments] = this.patchValidator('.removeField')
      .arityIsTwo(arguments)
      .validateAndAggregate()

    return this.copy({
      invalidArguments,
      addFieldModification: {
        fieldPath: fieldName,
        action: 'REMOVE_FIELD',
      },
    })
  }

  private patchValidator(operatorName: string) {
    return new FieldModificationsValidator(
      operatorName,
      this.ownInvalidArguments
    )
  }
}

class FieldModificationsValidator extends AggregatingValidator {
  constructor(public operatorName: string, previousInvalidArguments: string[]) {
    super(previousInvalidArguments)
    this.operatorName = operatorName
  }

  isNumber(specifier: string, operand: any) {
    return this.addValidation(
      () => isNumber(operand),
      () =>
        messages.queryValidations.isNumber(
          this.operatorName,
          specifier,
          operand
        )
    )
  }
}
